import java.util.*;import java.io.*;import com.google.gson.*;
public final class Models{
 // Animation JSON is immutable after loading. Compile each scalar and keyframe timeline once.
 static final Map<JsonElement,Expr.Node> numbers=new IdentityHashMap<JsonElement,Expr.Node>();
 static final Map<JsonElement,NavigableMap<Double,JsonElement>> timelines=new IdentityHashMap<JsonElement,NavigableMap<Double,JsonElement>>();

 public static class Bone{String name,parent;double[] pivot={0,0,0},rotation={0,0,0};List<float[]> faces=new ArrayList<float[]>();List<float[]>[] lods;}
 public static class Model{public List<Bone> bones=new ArrayList<Bone>();public Map<String,Bone> byName=new LinkedHashMap<String,Bone>();public JsonObject animations,config;public boolean mini,headHat,hat,duo,wings,aura,balloon,companion,skinMini;public double hatOffset;public String duoFirst="lelouch_",duoSecond="cc_";public List<String> activeAnimations;public int width=1024,height=1024;}
 public static class Mat{double[] m=new double[16];public Mat(){m[0]=m[5]=m[10]=m[15]=1;}Mat(double[] x){m=x;}public Mat mul(Mat b){double[] a=m,c=new double[16];for(int j=0;j<4;j++){int q=j*4;double x=b.m[q],y=b.m[q+1],z=b.m[q+2],w=b.m[q+3];for(int i=0;i<4;i++)c[q+i]=a[i]*x+a[4+i]*y+a[8+i]*z+a[12+i]*w;}return new Mat(c);}public Mat move(double x,double y,double z){double[] a=m.clone();for(int i=0;i<4;i++)a[12+i]=m[i]*x+m[4+i]*y+m[8+i]*z+m[12+i];return new Mat(a);}public Mat scale(double x,double y,double z){double[] a=m.clone();for(int i=0;i<4;i++){a[i]*=x;a[4+i]*=y;a[8+i]*=z;}return new Mat(a);}public Mat rot(double x,double y,double z){for(int axis=0;axis<3;axis++){double angle=axis==0?x:axis==1?y:z;if(angle==0)continue;double a=Math.toRadians(angle),c=Math.cos(a),s=Math.sin(a);int first=axis==0?4:0,second=axis==2?4:8;for(int i=0;i<4;i++){double u=m[first+i],v=m[second+i];if(axis==1){m[first+i]=u*c-v*s;m[second+i]=u*s+v*c;}else{m[first+i]=u*c+v*s;m[second+i]=-u*s+v*c;}}}return this;}public Mat bedrock(double x,double y,double z){return rot(0,0,z).rot(0,-y,0).rot(-x,0,0);}public double[] point(double x,double y,double z){return new double[]{m[0]*x+m[4]*y+m[8]*z+m[12],m[1]*x+m[5]*y+m[9]*z+m[13],m[2]*x+m[6]*y+m[10]*z+m[14]};}}
 static double[] array(JsonElement e,double fallback){double[] a={fallback,fallback,fallback};if(e==null)return a;if(e.isJsonPrimitive()){Arrays.fill(a,e.getAsDouble());return a;}if(e.isJsonArray())for(int i=0;i<Math.min(3,e.getAsJsonArray().size());i++)a[i]=e.getAsJsonArray().get(i).getAsDouble();return a;}
 public static Model load(Assets.Entry e)throws Exception{Model m=new Model();m.config=e.config;m.hat=e.slot.equals("hat");m.companion=e.slot.equals("companion");m.skinMini=e.config.has("skin_pet")&&e.config.get("skin_pet").getAsBoolean();m.wings=e.name.equals("Geass Wings");m.aura=e.name.equals("Geass Aura");m.balloon=e.slot.equals("balloon");m.duo=e.name.equals("Lelouch & C.C.")||e.name.startsWith("Shinji & Asuka");if(e.name.startsWith("Shinji & Asuka")){m.duoFirst="shinji_";m.duoSecond="asuka_";}if(e.slot.equals("cloak")){Bone b=new Bone();b.name="cape";b.pivot=new double[]{0,23,2.4};double[] uv={20d/352,20d/272,152d/352,248d/272};add(b,new double[][]{{-5,7,2.6},{5,7,2.6},{5,23,2.6},{-5,23,2.6}},new double[]{0,0,-1},uv);add(b,new double[][]{{5,7,2.7},{-5,7,2.7},{-5,23,2.7},{5,23,2.7}},new double[]{0,0,1},uv);m.bones.add(b);m.byName.put(b.name,b);return m;}
 String uri=e.config.get("model").getAsString();JsonObject root=Assets.json(Assets.path(uri)).getAsJsonObject();JsonObject geo=root.getAsJsonArray("minecraft:geometry").get(0).getAsJsonObject();JsonObject desc=geo.getAsJsonObject("description");if(desc.has("texture_width"))m.width=desc.get("texture_width").getAsInt();if(desc.has("texture_height"))m.height=desc.get("texture_height").getAsInt();
 for(JsonElement el:geo.getAsJsonArray("bones")){JsonObject o=el.getAsJsonObject();Bone b=new Bone();b.name=o.get("name").getAsString();b.parent=Assets.str(o,"parent",null);b.pivot=array(o.get("pivot"),0);b.rotation=array(o.get("rotation"),0);m.bones.add(b);m.byName.put(b.name,b);if(o.has("cubes"))for(JsonElement cube:o.getAsJsonArray("cubes"))cube(m,b,cube.getAsJsonObject());String mesh="assets/verity/dev_cosmetics/tung_meshes/"+b.name+".mesh";
 if(o.has("mesh"))mesh=Assets.path(o.get("mesh").getAsString());
 if(!Assets.files.containsKey(mesh)&&e.name.startsWith("Tung")&&b.name.startsWith("verity_"))mesh="assets/verity/dev_cosmetics/tung_meshes/"+b.name.replace("verity_","tung_")+".mesh";
 if(!Assets.files.containsKey(mesh)){if(b.name.equals("verity"))mesh="assets/verity/dev_cosmetics/verity/verity.mesh";else if(uri.contains("/fedora/")&&b.name.equals("bipedHead"))mesh="assets/verity/dev_cosmetics/fedora/fedora.mesh";else if(b.name.equals("verity_balloon"))mesh="assets/verity/dev_cosmetics/balloon/balloon.mesh";else if(b.name.startsWith("verity_orb_"))mesh="assets/verity/dev_cosmetics/aura/orb.mesh";else if(b.name.equals("verity_left_boot"))mesh="assets/verity/dev_cosmetics/shoes/left.mesh";else if(b.name.equals("verity_right_boot"))mesh="assets/verity/dev_cosmetics/shoes/right.mesh";}
 if(Assets.files.containsKey(mesh)){try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(Assets.files.get(mesh)))){if(in.readInt()!=1448237361)throw new IOException("Native mesh header invalid");int count=in.readInt();if(count<0||count>200000)throw new IOException("Invalid mesh size");b.faces.clear();for(int i=0;i<count;i++){float[] face=new float[32];for(int j=0;j<32;j++)face[j]=in.readFloat();for(int j=0;j<4;j++)for(int k=0;k<3;k++)face[j*8+k]*=16;b.faces.add(face);}}}}
 if(e.config.has("animation")&&e.config.get("animation").isJsonPrimitive()){JsonObject a=Assets.json(Assets.path(e.config.get("animation").getAsString())).getAsJsonObject();m.animations=a.getAsJsonObject("animations");}m.mini=m.byName.containsKey("mini_me")||(m.byName.containsKey("lelouch_mini_me")||m.byName.containsKey("shinji_mini_me"));m.headHat=m.hat&&m.mini;fit(m);for(Bone b:m.bones)MeshLods.attach(b,"model/"+e.id+"/"+b.name);return m;}
 static void cube(Model m,Bone b,JsonObject o){if((m.wings||m.aura)&&o.has("uv")&&o.get("uv").isJsonObject()&&o.getAsJsonObject("uv").has("north")){JsonObject north=o.getAsJsonObject("uv").getAsJsonObject("north");if(north.getAsJsonArray("uv").get(0).getAsDouble()>=64&&o.getAsJsonArray("size").get(1).getAsDouble()<.1)return;}double[] p=array(o.get("origin"),0),s=array(o.get("size"),0);double inflate=o.has("inflate")?o.get("inflate").getAsDouble():0;for(int i=0;i<3;i++){p[i]-=inflate;s[i]+=inflate*2;}double x=p[0],y=p[1],z=p[2],X=x+s[0],Y=y+s[1],Z=z+s[2];String[] ns={"north","south","west","east","up","down"};double[][][] points={{{x,y,z},{X,y,z},{X,Y,z},{x,Y,z}},{{X,y,Z},{x,y,Z},{x,Y,Z},{X,Y,Z}},{{x,y,Z},{x,y,z},{x,Y,z},{x,Y,Z}},{{X,y,z},{X,y,Z},{X,Y,Z},{X,Y,z}},{{x,Y,z},{X,Y,z},{X,Y,Z},{x,Y,Z}},{{x,y,Z},{X,y,Z},{X,y,z},{x,y,z}}};double[][] normals={{0,0,-1},{0,0,1},{-1,0,0},{1,0,0},{0,1,0},{0,-1,0}};JsonElement uv=o.get("uv");Mat transform=new Mat();if(o.has("rotation")){double[] pivot=array(o.get("pivot"),0),r=array(o.get("rotation"),0);transform=transform.move(pivot[0],pivot[1],pivot[2]).bedrock(r[0],r[1],r[2]).move(-pivot[0],-pivot[1],-pivot[2]);}
 for(int f=0;f<6;f++){double[] rect={0,0,1,1};if(uv!=null&&uv.isJsonObject()){if(!uv.getAsJsonObject().has(ns[f]))continue;JsonObject u=uv.getAsJsonObject().getAsJsonObject(ns[f]);JsonArray v=u.getAsJsonArray("uv"),d=u.getAsJsonArray("uv_size");rect=new double[]{v.get(0).getAsDouble()/m.width,v.get(1).getAsDouble()/m.height,d.get(0).getAsDouble()/m.width,d.get(1).getAsDouble()/m.height};}else if(uv!=null&&uv.isJsonArray()){JsonArray u=uv.getAsJsonArray();rect=new double[]{u.get(0).getAsDouble()/m.width,u.get(1).getAsDouble()/m.height,s[0]/m.width,s[1]/m.height};}
 double[][] ps=new double[4][];for(int i=0;i<4;i++)ps[i]=transform.point(points[f][i][0],points[f][i][1],points[f][i][2]);double[] n=normals[f],tm=transform.m;add(b,ps,new double[]{tm[0]*n[0]+tm[4]*n[1]+tm[8]*n[2],tm[1]*n[0]+tm[5]*n[1]+tm[9]*n[2],tm[2]*n[0]+tm[6]*n[1]+tm[10]*n[2]},rect);}}
 static void add(Bone b,double[][] ps,double[] normal,double[] uv){float[] face=new float[32];double[][] coords={{uv[0],uv[1]+uv[3]},{uv[0]+uv[2],uv[1]+uv[3]},{uv[0]+uv[2],uv[1]},{uv[0],uv[1]}};for(int i=0;i<4;i++){for(int j=0;j<3;j++){face[i*8+j]=(float)ps[i][j];face[i*8+3+j]=(float)normal[j];}face[i*8+6]=(float)coords[i][0];face[i*8+7]=(float)coords[i][1];}b.faces.add(face);}
 static double number(JsonElement e,Expr.Context c,double fallback){if(e==null||!e.isJsonPrimitive())return fallback;Expr.Node n=numbers.get(e);if(n==null){JsonPrimitive p=e.getAsJsonPrimitive();if(p.isNumber()){final double v=p.getAsDouble();n=x->v;}else{final String text=p.getAsString();try{final double v=Double.parseDouble(text);n=x->v;}catch(NumberFormatException ignored){n=x->Expr.eval(text,x);}}numbers.put(e,n);}return n.eval(c);}
 static double[] vector(JsonElement e,Expr.Context c,double fallback,double length){double[] out={fallback,fallback,fallback};if(e==null)return out;if(e.isJsonObject()){JsonObject o=e.getAsJsonObject();if(o.has("vector"))return vector(o.get("vector"),c,fallback,length);NavigableMap<Double,JsonElement> keys=timelines.get(e);if(keys==null){keys=new TreeMap<Double,JsonElement>();for(Map.Entry<String,JsonElement> k:o.entrySet())try{keys.put(Double.parseDouble(k.getKey()),k.getValue());}catch(NumberFormatException ignored){}timelines.put(e,keys);}if(keys.isEmpty())return out;double time=length>0?c.time%length:c.time;Map.Entry<Double,JsonElement> low=keys.floorEntry(time),high=keys.ceilingEntry(time);if(low==null)low=keys.firstEntry();if(high==null)high=keys.lastEntry();double[] a=vector(low.getValue(),c,fallback,length),b=vector(high.getValue(),c,fallback,length);double t=high.getKey().equals(low.getKey())?0:(time-low.getKey())/(high.getKey()-low.getKey());if(high.getValue().isJsonObject()&&high.getValue().getAsJsonObject().has("easing")){String ease=high.getValue().getAsJsonObject().get("easing").getAsString();if(ease.equals("easeInOutSine"))t=-(Math.cos(Math.PI*t)-1)/2;else if(ease.equals("easeInOutQuad"))t=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;else if(ease.equals("easeInOutCubic"))t=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;}for(int i=0;i<3;i++)out[i]=a[i]+(b[i]-a[i])*t;return out;}if(e.isJsonArray()){for(int i=0;i<Math.min(3,e.getAsJsonArray().size());i++)out[i]=number(e.getAsJsonArray().get(i),c,fallback);}else Arrays.fill(out,number(e,c,fallback));return out;}

 static void animations(JsonElement value,Expr.Context c,List<String> out){if(value==null)return;if(value.isJsonPrimitive()){out.add(value.getAsString());return;}if(value.isJsonObject())for(Map.Entry<String,JsonElement> e:value.getAsJsonObject().entrySet())if(number(e.getValue(),c,0)!=0)out.add(e.getKey());}
 public static List<String> active(Model m,Expr.Context c,boolean walking){List<String> out=new ArrayList<String>();if(m.config!=null&&m.config.has("state_machine")){JsonObject state=m.config.getAsJsonObject("state_machine");if(state.has("anim"))animations(state.get("anim"),c,out);if(state.has("controllers"))for(JsonElement controller:state.getAsJsonArray("controllers")){JsonObject ctrl=controller.getAsJsonObject();if(!ctrl.has("states"))continue;for(JsonElement el:ctrl.getAsJsonArray("states")){JsonObject st=el.getAsJsonObject();if(number(st.get("plays_when"),c,1)!=0){animations(st.get("anim"),c,out);break;}}}}else if(m.config!=null&&m.config.has("default_anim"))animations(m.config.get("default_anim"),c,out);if(out.isEmpty()&&m.animations!=null){if(m.animations.has("main"))out.add("main");else if(m.animations.has("flight"))out.add("flight");else if(m.animations.has("idle"))out.add("idle");else if(!m.animations.entrySet().isEmpty())out.add(m.animations.entrySet().iterator().next().getKey());}if(walking&&m.animations!=null&&m.animations.has("walk"))out.add(c.running&&m.animations.has("run")?"run":"walk");return out;}

 static void fit(Model m){
  if(m.byName.containsKey("tung_watch_root")){Bone arm=new Bone();arm.name="bipedRightArm";arm.pivot=new double[]{4.6875,20.625,0};m.bones.add(0,arm);m.byName.put(arm.name,arm);double[] shift={5.625-1.285*.82,12.7-16.635*.82,0};for(Bone b:m.bones)if(b!=arm){for(int k=0;k<3;k++)b.pivot[k]=b.pivot[k]*.82+shift[k];for(float[] face:MeshLods.geometry(b))for(int v=0;v<4;v++)for(int k=0;k<3;k++)face[v*8+k]=(float)(face[v*8+k]*.82+shift[k]);}m.byName.get("tung_watch_root").parent=arm.name;}

  if(m.balloon)for(Bone b:m.bones)if(b.name.equals("verity_balloon")||b.name.equals("tung_balloon")){Bone knot=m.byName.get(b.parent);if(knot==null||b.faces.isEmpty())continue;double[] low={1e9,1e9,1e9},high={-1e9,-1e9,-1e9};for(float[] f:b.faces)for(int i=0;i<4;i++)for(int k=0;k<3;k++){low[k]=Math.min(low[k],f[i*8+k]);high[k]=Math.max(high[k],f[i*8+k]);}double sx=0,sz=0;int count=0;for(float[] f:b.faces)for(int i=0;i<4;i++)if(Math.abs(f[i*8+1]-low[1])<.001){sx+=f[i*8];sz+=f[i*8+2];count++;}double[] delta={knot.pivot[0]-sx/Math.max(1,count),knot.pivot[1]-low[1],knot.pivot[2]-sz/Math.max(1,count)};for(float[] f:MeshLods.geometry(b))for(int i=0;i<4;i++)for(int k=0;k<3;k++)f[i*8+k]+=delta[k];}
  if(m.hat){Expr.Context c=new Expr.Context();c.time=2;m.activeAnimations=active(m,c,false);Map<String,Mat> done=new HashMap<String,Mat>();double bottom=1e9;for(Bone b:m.bones){if(m.headHat&&!b.name.equals("torso"))continue;Mat pose=pose(m,b,c,false,done,0,0);for(float[] f:b.faces)for(int i=0;i<4;i++)bottom=Math.min(bottom,pose.point(f[i*8],f[i*8+1],f[i*8+2])[1]);}if(bottom<1e8)m.hatOffset=(m.headHat?29.0:29.65)-bottom;}
 }
 public static Mat pose(Model m,Bone b,Expr.Context c,boolean walking,Map<String,Mat> done,double headYaw,double pitch){if(done.containsKey(b.name))return done.get(b.name);Mat parent=b.parent!=null&&m.byName.containsKey(b.parent)?pose(m,m.byName.get(b.parent),c,walking,done,headYaw,pitch):new Mat();double[] pos={0,0,0},rot={0,0,0},scale={1,1,1};if(m.animations!=null)for(String anim:m.activeAnimations!=null?m.activeAnimations:active(m,c,walking)){if(!m.animations.has(anim))continue;JsonObject a=m.animations.getAsJsonObject(anim);if(!a.has("bones")||!a.getAsJsonObject("bones").has(b.name))continue;JsonObject v=a.getAsJsonObject("bones").getAsJsonObject(b.name);double len=a.has("animation_length")?a.get("animation_length").getAsDouble():0;if(v.has("position"))pos=vector(v.get("position"),c,0,len);if(v.has("rotation"))rot=vector(v.get("rotation"),c,0,len);if(v.has("scale"))scale=vector(v.get("scale"),c,1,len);}

 if(m.companion&&m.mini&&!walking){
  if(b.name.equals("mini_me")||b.name.endsWith("_mini_me")){pos[1]=0;}
  if(b.name.equals("torso")||b.name.endsWith("_torso")){rot=new double[]{0,0,0};pos[1]=-.2+Math.sin(c.time*1.8)*.035;}
  if(b.name.equals("headtilt")||b.name.endsWith("_headtilt"))rot=new double[]{0,Math.sin(c.time*.43)*18+Math.sin(c.time*.17)*7,0};
  if(b.name.equals("head")||b.name.endsWith("_head")){rot=new double[]{Math.sin(c.time*.7)*2,0,0};pos[1]=0;}
  if(b.name.endsWith("left_arm")||b.name.endsWith("right_arm"))rot=new double[]{0,0,Math.sin(c.time*1.4)*.8};
  if(b.name.endsWith("left_leg")||b.name.endsWith("right_leg"))rot=new double[]{0,b.name.endsWith("left_leg")?-10:10,0};
 }
 if(m.mini&&!m.headHat&&!m.skinMini&&(b.name.endsWith("left_arm")||b.name.endsWith("right_arm"))){rot[2]=-rot[2]-2*b.rotation[2];}
 if(m.duo&&(b.name.equals(m.duoFirst+"left_arm")||b.name.equals(m.duoSecond+"right_arm"))){rot[0]=-b.rotation[0];rot[1]=-b.rotation[1];rot[2]=(b.name.startsWith(m.duoFirst)?34:-34)-b.rotation[2];}
 if(m.duo&&(b.name.endsWith("_torso")||b.name.endsWith("_mini_me"))){rot[0]=rot[1]=rot[2]=0;pos[1]=walking?Math.sin(c.time*16)*.14:Math.sin(c.time*3)*.025;}
 if(m.headHat&&(b.name.equals("left_arm")||b.name.equals("right_arm")))pos[0]+=b.name.equals("left_arm")?-.28:.28;
 if(m.headHat&&(b.name.equals("left_leg")||b.name.equals("right_leg"))){boolean left=b.name.equals("left_leg");rot=new double[]{-45,left?-40:40,left?-6:6};pos=new double[]{left?.8:-.8,-.1,-.55};}
 if(b.name.equals("bipedLeftLeg")||b.name.equals("bipedRightLeg")){boolean left=b.name.equals("bipedLeftLeg");rot[0]+=Math.toDegrees(Math.cos(c.limbPos*.6662+(left?Math.PI:0))*1.4*c.limbSpeed);if(c.crouching){pos[1]-=.2;pos[2]+=4;}}
 if(b.name.equals("bipedLeftArm")||b.name.equals("bipedRightArm")){boolean left=b.name.equals("bipedLeftArm");rot[0]+=Math.toDegrees(Math.cos(c.limbPos*.6662+(left?0:Math.PI))*c.limbSpeed);}
 if(m.wings&&(b.name.equals("geass_wing_left")||b.name.equals("geass_wing_right"))){rot[0]=-rot[0];rot[1]=-rot[1];}
 if(m.balloon&&b.name.startsWith("tether_"))rot[2]+=Math.max(-8,Math.min(8,c.right*1.6));
 if(b.name.equals("rei_flight")){double phase=c.time*35;double radius=14+Math.sin(Math.toRadians(c.time*23))*.5;pos[0]=Math.cos(Math.toRadians(phase))*radius;pos[2]=Math.sin(Math.toRadians(phase))*radius;pos[1]=20+Math.sin(Math.toRadians(c.time*70))*1.1;rot[0]=0;rot[1]=phase-90;rot[2]=0;}
 if(b.name.equals("bipedHead")){rot[0]=pitch-b.rotation[0];rot[1]=headYaw-b.rotation[1];rot[2]=-b.rotation[2];}
 if(b.name.equals("bipedRightArm")&&c.armRig){rot=new double[]{c.armRotX,c.armRotY,c.armRotZ};pos=new double[]{c.armX-b.pivot[0],c.armY-b.pivot[1],c.armZ-b.pivot[2]};}
 if(b.name.equals("bipedHead")&&c.headRig){rot=new double[]{c.headRotX,c.headRotY,c.headRotZ};pos=new double[]{c.headX-b.pivot[0],c.headY-22.5,c.headZ-b.pivot[2]};}
 double pivotY=b.name.equals("bipedHead")?22.5:b.pivot[1];Mat result=parent.move(pos[0],pos[1],pos[2]).move(b.pivot[0],pivotY,b.pivot[2]).bedrock(b.rotation[0]+rot[0],b.rotation[1]+rot[1],b.rotation[2]+rot[2]).scale(scale[0],scale[1],scale[2]).move(-b.pivot[0],-pivotY,-b.pivot[2]);if(b.name.equals("bipedHead"))result=result.move(0,m.hatOffset,0);done.put(b.name,result);return result;}
}
